<template>
	<view class="journal-manage" :class="{night: night}">
		<view class="topbar" :style="{paddingTop: StatusBar + 'px'}">
			<view class="topbar-inner"><text class="cuIcon-back" @tap="back"></text><text class="topbar-title">见字编辑部</text><text class="topbar-note">独立刊物体系</text></view>
		</view>
		<view class="content" :style="{paddingTop: (StatusBar + 58) + 'px'}">
			<view class="intro"><view><text class="eyebrow">CAMPUS EDITIONS</text><text class="intro-title">把刊物，编成一件作品</text><text class="intro-desc">管理刊物结构、编辑排序，并在同一处完成投稿审核。</text></view><view class="intro-mark">见<br/>字</view></view>
			<view class="tabs"><text v-if="isAdministrator" :class="{active: tab==='journals'}" @tap="switchTab('journals')">刊物管理</text><text :class="{active: tab==='articles'}" @tap="switchTab('articles')">投稿审核</text></view>

			<view v-if="tab==='journals' && isAdministrator" class="panel">
				<view class="panel-head"><view><text class="panel-title">刊物</text><text class="panel-sub">{{journals.length}} 本已加载</text></view><button class="primary" @tap="openJournal()"><text class="cuIcon-add"></text> 新增刊物</button></view>
				<view v-if="!journalLoading && !journals.length" class="empty"><text class="empty-mark">○</text><text>还没有刊物</text><text class="empty-sub">先创建一本刊物，投稿入口才会对用户开放。</text></view>
				<view v-for="item in journals" :key="item.id" class="journal-row">
					<view class="journal-cover" :style="{backgroundImage: item.coverUrl ? 'url('+item.coverUrl+')' : ''}"><text v-if="!item.coverUrl">见字</text></view>
					<view class="journal-main"><view class="journal-title-line"><text class="journal-title">{{item.name}}</text><text class="badge" :class="item.status==1?'on':'off'">{{item.status==1?'已启用':'已隐藏'}}</text><text v-if="item.featured==1" class="badge featured">推荐</text></view><text class="journal-desc">{{item.description || '还没有刊物简介'}}</text><text class="journal-meta">{{item.articleCount || 0}} 篇文章 · 排序 {{item.sortOrder || 0}} · 热门权重 {{item.hotWeight || 0}}</text></view>
					<view class="row-actions"><text @tap="openJournal(item)">编辑</text><text @tap="toggleJournal(item)">{{item.status==1?'隐藏':'启用'}}</text></view>
				</view>
			</view>

			<view v-else class="panel">
				<view class="filter-tabs"><text v-for="x in articleStatuses" :key="x.value" :class="{active: articleStatus===x.value}" @tap="setArticleStatus(x.value)">{{x.label}}</text></view>
				<view v-if="!articleLoading && !articles.length" class="empty compact"><text class="empty-mark">○</text><text>暂无投稿</text><text class="empty-sub">新的投稿会出现在这里。</text></view>
				<view v-for="item in articles" :key="item.id" class="article-row"><view class="article-state" :class="articleStateClass(item.status)">{{articleState(item.status)}}</view><view class="article-main"><text class="article-title">{{item.title}}</text><text class="article-meta">{{item.journalName || '未命名刊物'}} · {{item.authorName || '匿名作者'}} · {{formatDate(item.created)}}</text><text v-if="item.reviewReason" class="article-reason">退回理由：{{item.reviewReason}}</text></view><view class="row-actions article-actions"><text @tap="previewArticle(item)">查看</text><text v-if="item.status==='submitted'" class="publish" @tap="review(item,'published')">发布</text><text v-if="item.status==='submitted'" class="reject" @tap="review(item,'rejected')">退回</text><text v-if="item.status==='published'" class="reject" @tap="review(item,'hidden')">隐藏</text></view></view>
				<view v-if="articles.length" class="load-more" @tap="loadArticles(true)">{{articleMore}}</view>
			</view>
		</view>

		<view v-if="journalEditor" class="modal" @tap="closeJournal"><view class="sheet" @tap.stop @click.stop><view class="sheet-head"><text @tap.stop="closeJournal">取消</text><text class="sheet-title">{{journalForm.id ? '编辑刊物' : '新增刊物'}}</text><text class="save" @tap.stop="saveJournal">保存</text></view><view class="sheet-scroll" @tap.stop><view class="form-item"><text>刊物名称</text><input v-model="journalForm.name" maxlength="80" placeholder="例如：南风杂志" @tap.stop @click.stop></input></view><view class="form-item"><text>Slug</text><input v-model="journalForm.slug" maxlength="100" placeholder="用于刊物链接，可留空自动生成" @tap.stop @click.stop></input></view><view class="form-item"><text>简介</text><textarea v-model="journalForm.description" maxlength="500" placeholder="一句话介绍刊物的内容与气质" @tap.stop @click.stop></textarea></view><view class="form-item"><text>标签</text><input v-model="journalForm.tags" maxlength="500" placeholder="校园,人物,观点" @tap.stop @click.stop></input></view><view class="form-item"><text>封面图地址</text><view class="input-action"><input v-model="journalForm.coverUrl" maxlength="500" placeholder="https://..." @tap.stop @click.stop></input><text @tap.stop="chooseImage('coverUrl')">上传</text></view></view><view class="form-item"><text>横幅图地址</text><view class="input-action"><input v-model="journalForm.bannerUrl" maxlength="500" placeholder="https://..." @tap.stop @click.stop></input><text @tap.stop="chooseImage('bannerUrl')">上传</text></view></view><view class="form-grid"><view class="form-item"><text>排序</text><input v-model="journalForm.sortOrder" type="number" @tap.stop @click.stop></input></view><view class="form-item"><text>热门权重</text><input v-model="journalForm.hotWeight" type="number" @tap.stop @click.stop></input></view></view><view class="switch-row"><view @tap.stop="journalForm.featured=journalForm.featured==1?0:1"><text>首页推荐</text><small>推荐刊物优先展示</small></view><switch :checked="journalForm.featured==1" color="#2e6a5a" @change="journalForm.featured=$event.detail.value?1:0" /></view></view></view></view>
		<view v-if="reasonEditor" class="modal" @tap="reasonEditor=false"><view class="reason-sheet" @tap.stop><text class="sheet-title">退回投稿</text><textarea v-model="reviewReason" maxlength="500" placeholder="填写退回理由，作者会在投稿记录中看到" /><view class="reason-actions"><button @tap="reasonEditor=false">取消</button><button class="primary" @tap="confirmReject">确认退回</button></view></view></view>
	</view>
</template>

<script>
import { localStorage } from '../../js_sdk/mp-storage/mp-storage/index.js'

const blankJournal = () => ({ id: 0, name: '', slug: '', description: '', tags: '', coverUrl: '', bannerUrl: '', sortOrder: 0, featured: 0, hotWeight: 0 })
export default {
	data() { return { StatusBar: this.StatusBar, token: '', group: '', tab: 'journals', night: false, journals: [], journalLoading: false, journalEditor: false, journalForm: blankJournal(), articleStatus: 'submitted', articleStatuses: [{label:'待审核',value:'submitted'}, {label:'已发布',value:'published'}, {label:'已退回',value:'rejected'}, {label:'已隐藏',value:'hidden'}, {label:'全部',value:''}], articles: [], articleLoading: false, articlePage: 1, articleMore: '加载更多', reasonEditor: false, reviewReason: '', rejecting: null } },
	computed: { isAdministrator() { return this.group === 'administrator'; } },
	onLoad(query) { this.token = localStorage.getItem('token') || ''; try { this.group = JSON.parse(localStorage.getItem('userinfo') || '{}').group || ''; } catch (e) {} if (this.group !== 'administrator') this.tab = 'articles'; else if (query && query.tab === 'articles') this.tab = 'articles'; this.loadJournals(); if (this.tab === 'articles') this.loadArticles(false); },
	onShow() { this.token = localStorage.getItem('token') || this.token; },
	methods: {
		back() { uni.navigateBack({ delta: 1 }) },
		switchTab(v) { this.tab = v; if (v === 'articles' && !this.articles.length) this.loadArticles(false); },
		loadJournals() { this.journalLoading = true; this.$Net.request({ url: this.$API.journalList(), data: { token: this.token, page: 1, limit: 50, includeHidden: 1 }, method: 'get', dataType: 'json', success: r => { this.journals = r.data && r.data.code === 1 && Array.isArray(r.data.data) ? r.data.data : []; this.journalLoading = false }, fail: () => { this.journalLoading = false; } }); },
		openJournal(item) { this.journalForm = item ? Object.assign(blankJournal(), item) : blankJournal(); this.journalEditor = true; },
		chooseImage(field) { uni.chooseImage({ count: 1, sizeType: ['compressed'], sourceType: ['album', 'camera'], success: res => { const path = res.tempFilePaths && res.tempFilePaths[0]; if (!path) return; uni.showLoading({ title: '上传中' }); uni.uploadFile({ url: this.$API.upload(), filePath: path, name: 'file', formData: { token: this.token }, success: response => { try { const body = JSON.parse(response.data); if (body.code === 1 && body.data && body.data.url) this.journalForm[field] = body.data.url; else uni.showToast({ title: body.msg || '上传失败', icon: 'none' }); } catch (e) { uni.showToast({ title: '上传响应无效', icon: 'none' }); } }, fail: () => uni.showToast({ title: '上传失败', icon: 'none' }), complete: () => uni.hideLoading() }); } }); },
		closeJournal() { this.journalEditor = false; },
		saveJournal() { if (this.journalForm.name.trim().length < 2) return uni.showToast({ title: '刊物名称至少需要2个字', icon: 'none' }); uni.showLoading({ title: '保存中' }); this.$Net.request({ url: this.$API.journalSave(), data: { token: this.token, params: JSON.stringify(this.journalForm) }, method: 'post', dataType: 'json', success: r => { uni.hideLoading(); if (r.data && r.data.code === 1) { this.journalEditor = false; uni.showToast({ title: '刊物已保存', icon: 'none' }); this.loadJournals(); } else uni.showToast({ title: r.data && r.data.msg || '保存失败', icon: 'none' }); }, fail: () => { uni.hideLoading(); uni.showToast({ title: '网络不太好，请稍后重试', icon: 'none' }); } }); },
		toggleJournal(item) { const next = item.status == 1 ? 0 : 1; uni.showModal({ title: next ? '启用刊物？' : '隐藏刊物？', content: next ? '启用后用户可以浏览并投稿。' : '隐藏后用户将无法浏览该刊物。', success: r => { if (!r.confirm) return; this.$Net.request({ url: this.$API.journalStatus(), data: { token: this.token, id: item.id, status: next }, method: 'get', dataType: 'json', success: res => { uni.showToast({ title: res.data && res.data.msg || '已更新', icon: 'none' }); if (res.data && res.data.code === 1) this.loadJournals(); } }); } }); },
		setArticleStatus(v) { this.articleStatus = v; this.loadArticles(false); },
		loadArticles(append) { if (this.articleLoading) return; this.articleLoading = true; const page = append ? this.articlePage + 1 : 1; this.$Net.request({ url: this.$API.journalArticleManage(), data: { token: this.token, status: this.articleStatus, page: page, limit: 20 }, method: 'get', dataType: 'json', success: r => { const rows = r.data && r.data.code === 1 && Array.isArray(r.data.data) ? r.data.data : []; this.articles = append ? this.articles.concat(rows) : rows; this.articlePage = page; this.articleMore = rows.length < 20 ? '没有更多投稿' : '加载更多'; this.articleLoading = false; }, fail: () => { this.articleLoading = false; } }); },
		articleState(v) { return { submitted: '待审核', published: '已发布', rejected: '已退回', hidden: '已隐藏', draft: '草稿' }[v] || v || '未知'; },
		articleStateClass(v) { return 'state-' + (v || 'draft'); },
		formatDate(v) { const d = new Date(Number(v) > 10000000000 ? Number(v) : Number(v) * 1000); return isNaN(d.getTime()) ? '' : d.getFullYear() + '.' + String(d.getMonth() + 1).padStart(2, '0') + '.' + String(d.getDate()).padStart(2, '0'); },
		previewArticle(item) { uni.navigateTo({ url: '/pages/journal/article?id=' + item.id }); },
		review(item, status) { if (status === 'rejected') { this.rejecting = item; this.reviewReason = ''; this.reasonEditor = true; return; } const title = status === 'published' ? '发布这篇投稿？' : '隐藏这篇文章？'; uni.showModal({ title, content: status === 'published' ? '发布后文章会出现在刊物和首页推荐流中。' : '隐藏后普通用户将无法看到这篇文章。', success: r => { if (r.confirm) this.submitReview(item, status, ''); } }); },
		confirmReject() { if (!this.rejecting) return; this.reasonEditor = false; this.submitReview(this.rejecting, 'rejected', this.reviewReason); },
		submitReview(item, status, reason) { uni.showLoading({ title: '处理中' }); this.$Net.request({ url: this.$API.journalArticleReview(), data: { token: this.token, id: item.id, status: status, reason: reason || '' }, method: 'get', dataType: 'json', success: r => { uni.hideLoading(); uni.showToast({ title: r.data && r.data.msg || '已更新', icon: 'none' }); if (r.data && r.data.code === 1) this.loadArticles(false); }, fail: () => { uni.hideLoading(); uni.showToast({ title: '网络不太好，请稍后重试', icon: 'none' }); } }); }
	}
}
</script>

<style scoped>
.journal-manage{min-height:100vh;background:#f4f1eb;color:#1d3029}.topbar{position:fixed;left:0;right:0;top:0;z-index:5;background:rgba(244,241,235,.96);backdrop-filter:blur(12px)}.topbar-inner{height:58px;display:flex;align-items:center;padding:0 22px;gap:16px}.topbar-inner>.cuIcon-back{font-size:20px;color:#49685d}.topbar-title{font:21px Georgia,serif}.topbar-note{margin-left:auto;font-size:10px;letter-spacing:1.5px;color:#91a099}.content{max-width:980px;margin:auto;padding-left:22px;padding-right:22px;padding-bottom:80px}.intro{display:flex;justify-content:space-between;align-items:flex-end;padding:38px 0 34px;border-bottom:1px solid #d7dfd8}.eyebrow{display:block;font-size:10px;letter-spacing:2px;color:#a0724d}.intro-title{display:block;margin-top:14px;font:clamp(30px,6vw,52px)/1.08 Georgia,serif;color:#25483d}.intro-desc{display:block;margin-top:14px;color:#76877e;font-size:13px}.intro-mark{width:68px;height:68px;border-radius:50%;background:#2d5c4f;color:#f8f5ed;text-align:center;padding-top:10px;box-sizing:border-box;font:22px/22px Georgia,serif;letter-spacing:3px}.tabs{display:flex;gap:28px;padding:24px 0 16px;border-bottom:1px solid #d7dfd8}.tabs text,.filter-tabs text{font-size:13px;color:#82928a;padding-bottom:10px}.tabs .active,.filter-tabs .active{color:#2f5e50;border-bottom:2px solid #a56f4b}.panel{padding-top:20px}.panel-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.panel-title{font:27px Georgia,serif}.panel-sub{margin-left:10px;color:#9aa79f;font-size:11px}.primary{border:0;border-radius:18px;background:#2e6657;color:#fff;padding:9px 15px;font-size:12px;line-height:1}.primary text{margin-right:4px}.journal-row,.article-row{display:flex;align-items:center;gap:16px;padding:16px 0;border-bottom:1px solid #d7dfd8}.journal-cover{width:58px;height:74px;flex:none;border-radius:5px;background:#315e50 center/cover no-repeat;display:flex;align-items:center;justify-content:center;color:#fff;font:18px Georgia,serif}.journal-main,.article-main{flex:1;min-width:0}.journal-title-line{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.journal-title{font:21px Georgia,serif;color:#24473c}.badge{padding:3px 7px;border-radius:10px;font-size:10px}.badge.on{background:#deece4;color:#3d765f}.badge.off{background:#ecebe7;color:#8a918e}.badge.featured{background:#f2e1d4;color:#9b6342}.journal-desc{display:block;margin-top:7px;color:#77877f;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.journal-meta,.article-meta{display:block;margin-top:8px;color:#9aa69f;font-size:11px}.row-actions{display:flex;gap:14px;flex:none;font-size:12px;color:#52796c}.row-actions text{cursor:pointer}.article-row{gap:12px}.article-state{width:48px;flex:none;text-align:center;padding:5px 3px;border-radius:12px;font-size:10px}.state-submitted{background:#f4e5d7;color:#9b6949}.state-published{background:#deece4;color:#3d765f}.state-rejected,.state-hidden{background:#ecebe7;color:#8a918e}.article-title{display:block;font:18px Georgia,serif;color:#294c40;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.article-reason{display:block;margin-top:6px;color:#a36d4f;font-size:11px}.article-actions .publish{color:#2e765c}.article-actions .reject{color:#a4664a}.filter-tabs{display:flex;gap:22px;margin-bottom:4px;overflow-x:auto;white-space:nowrap}.empty{text-align:center;padding:72px 20px;color:#6f8379}.empty.compact{padding:65px 20px}.empty-mark{display:block;font:42px Georgia,serif;color:#afc1b7}.empty-sub{display:block;margin-top:8px;color:#a0aaa4;font-size:12px}.load-more{text-align:center;padding:20px;color:#668277;font-size:12px}.modal{position:fixed;inset:0;z-index:20;background:#13221d66;display:flex;align-items:flex-end}.sheet,.reason-sheet{width:100%;height:88vh;max-height:88vh;overflow:hidden;background:#faf8f3;border-radius:20px 20px 0 0;box-sizing:border-box;pointer-events:auto}.sheet{padding:20px 22px 30px}.sheet-head{display:flex;justify-content:space-between;align-items:center;color:#628174;font-size:13px;min-height:34px}.sheet-title{font:22px Georgia,serif;color:#233f35}.save{color:#2e6a5a}.sheet-scroll{height:calc(88vh - 84px);max-height:none;margin-top:12px;overflow-y:auto;-webkit-overflow-scrolling:touch;pointer-events:auto}.form-item{margin-top:15px}.form-item>text{display:block;margin-bottom:7px;color:#62776d;font-size:12px}.form-item input,.form-item textarea,.reason-sheet textarea{width:100%;box-sizing:border-box;border:1px solid #d5dfd8;border-radius:7px;background:#fffdf9;padding:11px;font-size:14px;color:#243c34;pointer-events:auto;position:relative;z-index:1}.form-item textarea{min-height:82px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.switch-row{display:flex;justify-content:space-between;align-items:center;margin-top:18px;padding-top:16px;border-top:1px solid #dde4de}.switch-row text{display:block;color:#62776d;font-size:13px}.switch-row small{display:block;margin-top:4px;color:#9aa69f;font-size:11px}.reason-sheet{padding:24px 22px 32px}.reason-sheet textarea{height:110px;margin-top:18px}.reason-actions{display:flex;justify-content:flex-end;gap:12px;margin-top:18px}.reason-actions button{border:0;background:transparent;color:#6e8179;font-size:13px}.reason-actions .primary{background:#2e6657;color:#fff}@media(max-width:520px){.topbar-note{display:none}.intro{padding-top:28px}.intro-title{font-size:34px}.intro-mark{width:54px;height:54px;font-size:18px;line-height:18px}.journal-row{gap:11px}.journal-cover{width:48px;height:64px}.row-actions{gap:9px}.article-state{width:43px}.article-actions{flex-direction:column;align-items:flex-end;gap:7px}}
.night{background:#1e2522;color:#e6eee8}.night .topbar{background:rgba(30,37,34,.96)}.night .intro,.night .tabs,.night .journal-row,.night .article-row{border-color:#39463f}.night .intro-title,.night .panel-title,.night .journal-title,.night .article-title{color:#e3eee7}.night .intro-desc,.night .journal-desc,.night .journal-meta,.night .article-meta{color:#9eafa5}
.input-action{display:flex;align-items:center;gap:8px}.input-action input{flex:1}.input-action text{flex:none;padding:8px 11px;border-radius:6px;background:#e5eee8;color:#3f705f;font-size:12px}
.modal{pointer-events:auto}.sheet-scroll{touch-action:pan-y;overflow-y:auto;overflow-x:hidden}.sheet-head text,.input-action text,.switch-row{cursor:pointer}
.form-item uni-input{display:block;width:100%;height:44px;min-height:44px;box-sizing:border-box}.form-item uni-input .uni-input-wrapper{height:100%;display:flex;align-items:center}.form-item uni-input .uni-input-input{height:100%;line-height:44px;box-sizing:border-box}.input-action uni-input{flex:1}
</style>
